import { NodeRuntime, NodeServices } from "@effect/platform-node"
import { Console, Data, Effect, FileSystem } from "effect"

class PreviewScanError extends Data.TaggedError("PreviewScanError")<{
  readonly directory: string
  readonly cause: unknown
  readonly message: string
}> {}

const cacheDirectory = ".cache/previews"

const prunePreviews = Effect.gen(function*() {
  const fs = yield* FileSystem.FileSystem
  const entries = yield* fs.readDirectory(cacheDirectory).pipe(
    Effect.mapError((cause) => new PreviewScanError({
      directory: cacheDirectory,
      cause,
      message: `Could not list ${cacheDirectory}`,
    })),
  )
  const partials = entries.filter((name) => name.endsWith(".partial"))

  yield* Effect.forEach(
    partials,
    (name) => fs.remove(`${cacheDirectory}/${name}`),
    { concurrency: 4, discard: true },
  )

  yield* Console.log(`Removed ${partials.length} incomplete previews`)
})

prunePreviews.pipe(
  Effect.provide(NodeServices.layer),
  NodeRuntime.runMain,
)

